mapper.select:
SELECT dr.project_id, p.`name`, p.serial_number, p.short_name, IFNULL( SUM( dr.mete ), 0 ) mete FROM tech_deepen_record AS dr INNER JOIN contract_project AS p ON dr.project_id = p.id AND p.bool_delete_enum = 0 WHERE dr.bool_delete_enum = 0 AND product_type = 2
AND DATE_FORMAT( dr.create_time, '%Y' ) = #{year}
AND DATE_FORMAT( dr.create_time, '%m' ) = #{month}
and dr.project_id in
#{projectId}
GROUP BY dr.project_id ORDER BY IFNULL( SUM( dr.mete ), 0 ) DESC

SELECT dr.user_id, u.name AS user_name, SUM(dr.mete) AS mete FROM `tech_deepen_record` AS dr LEFT JOIN sys_user AS u ON dr.user_id = u.id AND u.bool_delete_enum = 0 WHERE dr.bool_delete_enum = 0 AND product_type = 2 AND DATE_FORMAT(dr.create_time,'%Y') = #{year}
AND DATE_FORMAT(dr.create_time,'%m') = #{month}
GROUP BY dr.user_id ORDER BY SUM(dr.mete) DESC

SELECT SUM( mete ) FROM tech_deepen_record WHERE bool_delete_enum = 0 AND product_type = 2 AND user_id = #{userId}
AND DATE_FORMAT(create_time,'%Y') = #{year}
AND DATE_FORMAT(create_time,'%m') = #{month}
GROUP BY user_id

SELECT * FROM ( SELECT dr.project_id, p.`name`, p.serial_number, p.short_name, IFNULL( SUM( dr.mete ), 0 ) mete, IFNULL((SELECT SUM( mete ) FROM plan_monomer_detail WHERE bool_delete_enum = 0 AND project_id = dr.project_id AND type = 1),0) AS plan_mete FROM tech_deepen_record AS dr INNER JOIN contract_project AS p ON dr.project_id = p.id AND p.bool_delete_enum = 0 WHERE dr.bool_delete_enum = 0 AND product_type = 2
AND DATE_FORMAT(p.create_time,'%Y') = #{year}
and dr.project_id in
#{projectId}
GROUP BY dr.project_id ) AS record
ORDER BY ( record.mete / record.plan_mete ) DESC
